package org.example.controller;

import javafx.beans.property.*;import javafx.collections.*;import javafx.fxml.FXML;import javafx.scene.control.*;import javafx.scene.layout.*;import org.example.api.recon.PurchaseReconApiClient;import org.example.service.PermissionService;import org.example.navigation.ScreenLifecycle;import org.example.util.*;import java.util.*;
public class ReconSupplierController implements ScreenLifecycle{
 @FXML private StackPane pageIcon,kpiTotalIcon,kpiActiveIcon,kpiImportIcon,kpiReconIcon;@FXML private Label kpiTotal,kpiActive,kpiImported,kpiRecons,lblEditorTitle,lblReference;@FXML private TextField txtSearch,txtName,txtGstin,txtPan,txtContact,txtPhone,txtEmail;@FXML private TextArea txtNotes;@FXML private ComboBox<String> cmbStatus;@FXML private Button btnNew,btnSave,btnRefresh;@FXML private VBox editorPanel;@FXML private HBox workspaceRow;@FXML private TableView<PurchaseReconApiClient.SupplierDto> table;@FXML private TableColumn<PurchaseReconApiClient.SupplierDto,String> colRef,colName,colGstin,colPhone,colSource,colStatus;@FXML private TableColumn<PurchaseReconApiClient.SupplierDto,Number> colCount;@FXML private TableColumn<PurchaseReconApiClient.SupplierDto,Void> colAction;
 private final PurchaseReconApiClient api=new PurchaseReconApiClient();private Dialog<ButtonType> editorDialog;private final ObservableList<PurchaseReconApiClient.SupplierDto> all=FXCollections.observableArrayList();private PurchaseReconApiClient.SupplierDto editing;
 @FXML private void initialize(){pageIcon.getChildren().setAll(IconFactory.icon("supplier",24));kpiTotalIcon.getChildren().setAll(IconFactory.icon("supplier",18));kpiActiveIcon.getChildren().setAll(IconFactory.icon("complete",18));kpiImportIcon.getChildren().setAll(IconFactory.icon("import",18));kpiReconIcon.getChildren().setAll(IconFactory.icon("reconcile",18));if(btnRefresh!=null)btnRefresh.setGraphic(IconFactory.compactIcon("refresh",14));if(btnNew!=null)btnNew.setGraphic(IconFactory.compactIcon("add",14));if(btnSave!=null)btnSave.setGraphic(IconFactory.compactIcon("save",14));cmbStatus.getItems().setAll("ACTIVE","INACTIVE");cmbStatus.setValue("ACTIVE");configureTable();btnNew.setDisable(!PermissionService.allowed("RECON_SUPPLIER.CREATE"));if(workspaceRow!=null&&editorPanel!=null){workspaceRow.getChildren().remove(editorPanel);editorPanel.setManaged(true);editorPanel.setVisible(true);}org.example.util.OperationalUiSupport.focusSearch(txtSearch);refresh();}
 private void configureTable(){colRef.setCellValueFactory(v->new SimpleStringProperty(s(v.getValue().reference())));colName.setCellValueFactory(v->new SimpleStringProperty(s(v.getValue().legalName())));colGstin.setCellValueFactory(v->new SimpleStringProperty(s(v.getValue().gstin())));colPhone.setCellValueFactory(v->new SimpleStringProperty(s(v.getValue().phone())));colCount.setCellValueFactory(v->new SimpleLongProperty(v.getValue().reconCount()));colSource.setCellValueFactory(v->new SimpleStringProperty(s(v.getValue().source())));colStatus.setCellValueFactory(v->new SimpleStringProperty(s(v.getValue().status())));colAction.setCellFactory(c->new TableCell<>(){private final MenuButton actions=new MenuButton("Actions");private PurchaseReconApiClient.SupplierDto row;{actions.setGraphic(IconFactory.compactIcon("actions",14));actions.getStyleClass().addAll("table-action-menu","approved-row-action");actions.setOnShowing(e->rebuild());IconFactory.decorateActionMenu(actions);}private void rebuild(){actions.getItems().clear();if(row==null)return;MenuItem view=new MenuItem("View",IconFactory.compactIcon("view",14));view.setOnAction(e->edit(row));MenuItem edit=new MenuItem("Edit",IconFactory.compactIcon("edit",14));edit.setDisable(!PermissionService.allowed("RECON_SUPPLIER.EDIT"));edit.setOnAction(e->edit(row));MenuItem del=new MenuItem("Delete",IconFactory.compactIcon("delete",14));del.getStyleClass().add("danger-menu-item");del.setDisable(!PermissionService.allowed("RECON_SUPPLIER.DELETE")||row.reconCount()>0);del.setOnAction(e->deleteSupplier(row));actions.getItems().setAll(view,edit,del);}@Override protected void updateItem(Void x,boolean empty){super.updateItem(x,empty);row=empty||getIndex()<0||getIndex()>=getTableView().getItems().size()?null:getTableView().getItems().get(getIndex());setGraphic(row==null?null:actions);}});IconFactory.applyTableHeaderIcon(colRef,"reference");IconFactory.applyTableHeaderIcon(colName,"supplier");IconFactory.applyTableHeaderIcon(colGstin,"tax");IconFactory.applyTableHeaderIcon(colPhone,"phone");IconFactory.applyTableHeaderIcon(colCount,"purchase");IconFactory.applyTableHeaderIcon(colSource,"source");IconFactory.applyTableHeaderIcon(colStatus,"status");IconFactory.applyTableHeaderIcon(colAction,"actions");table.setRowFactory(tv->{TableRow<PurchaseReconApiClient.SupplierDto> r=new TableRow<>();r.setOnMouseClicked(e->{if(e.getButton()!=javafx.scene.input.MouseButton.PRIMARY||e.getClickCount()!=1||r.isEmpty()||RegisterUiSupport.isInteractiveTableTarget(e.getPickResult().getIntersectedNode(),r))return;table.getSelectionModel().select(r.getItem());edit(r.getItem());e.consume();});return r;});}
 @Override public void onScreenShown(boolean reusedFromCache){org.example.util.OperationalUiSupport.focusSearch(txtSearch);if(reusedFromCache)refresh();}
 @FXML private void refresh(){String q=s(txtSearch.getText()).trim();org.example.util.OperationalUiSupport.showLoading(table,"Loading recon suppliers…");UiTaskExecutor.submitLatest("recon-supplier-load",()->api.searchSuppliers(q,100),list->{all.setAll(list==null?List.of():list);table.getItems().setAll(all);updateKpis();if(table.getItems().isEmpty())org.example.util.OperationalUiSupport.showEmpty(table,"No recon suppliers found","Create a Recon Supplier or update the search.");},failure->{org.example.util.OperationalUiSupport.showError(table,"Recon Supplier register could not load",failure);error(failure);});}
 @FXML private void applySearch(){refresh();}
 private void updateKpis(){kpiTotal.setText(String.valueOf(all.size()));kpiActive.setText(String.valueOf(all.stream().filter(x->"ACTIVE".equalsIgnoreCase(x.status())).count()));kpiImported.setText(String.valueOf(all.stream().filter(x->"IMPORT".equalsIgnoreCase(x.source())).count()));kpiRecons.setText(String.valueOf(all.stream().mapToLong(PurchaseReconApiClient.SupplierDto::reconCount).sum()));}
 private void deleteSupplier(PurchaseReconApiClient.SupplierDto row){if(row==null||!PermissionService.allowed("RECON_SUPPLIER.DELETE"))return;if(!ModernDialog.confirm(table,"Delete Recon Supplier","Delete "+row.legalName()+"?","Only suppliers with no Purchase Recon records can be deleted."))return;UiTaskExecutor.submitAction("recon-supplier-delete-"+row.id(),()->{api.deleteSupplier(row.id());return true;},ok->{ToastManager.success(table,"Recon Supplier deleted",row.legalName()+" was deleted.");refresh();},this::error);}
 @FXML private void newSupplier(){editing=null;txtName.clear();txtGstin.clear();txtPan.clear();txtContact.clear();txtPhone.clear();txtEmail.clear();txtNotes.clear();cmbStatus.setValue("ACTIVE");lblEditorTitle.setText("New Recon Supplier");lblReference.setText("Reference generated on save");btnSave.setDisable(!PermissionService.allowed("RECON_SUPPLIER.CREATE"));showEditor();}
 private void edit(PurchaseReconApiClient.SupplierDto x){if(x==null)return;editing=x;txtName.setText(s(x.legalName()));txtGstin.setText(s(x.gstin()));txtPan.setText(s(x.pan()));txtContact.setText(s(x.contactPerson()));txtPhone.setText(s(x.phone()));txtEmail.setText(s(x.email()));txtNotes.setText(s(x.notes()));cmbStatus.setValue(s(x.status()).isBlank()?"ACTIVE":x.status());lblEditorTitle.setText("Edit Recon Supplier");lblReference.setText(s(x.reference()));btnSave.setDisable(!PermissionService.allowed("RECON_SUPPLIER.EDIT"));showEditor();}
 private void showEditor(){if(editorDialog==null){editorDialog=new OwnedDialog<>();editorDialog.getDialogPane().setContent(editorPanel);editorDialog.getDialogPane().getButtonTypes().add(ButtonType.CLOSE);}editorDialog.setTitle(editing==null?"New Recon Supplier":"Recon Supplier Details");if(!editorDialog.isShowing())editorDialog.show();txtName.requestFocus();}
 @FXML private void cancelEdit(){if(editorDialog!=null&&editorDialog.isShowing())editorDialog.close();editing=null;}
 @FXML private void saveSupplier(){if(txtName.getText()==null||txtName.getText().isBlank()){ModernDialog.warning(table,"Recon Supplier","Name required","Enter the Trade / Legal Name.");return;}var req=new PurchaseReconApiClient.SupplierSaveRequest(editing==null?null:editing.id(),txtName.getText().trim(),s(txtGstin.getText()).trim(),s(txtPan.getText()).trim(),s(txtContact.getText()).trim(),s(txtPhone.getText()).trim(),s(txtEmail.getText()).trim(),s(txtNotes.getText()).trim(),cmbStatus.getValue(),editing==null?0L:editing.rowVersion());UiTaskExecutor.submitAction("recon-supplier-save",()->api.saveSupplier(req),saved->{ToastManager.success(table,"Recon Supplier saved",saved.reference()+" • "+saved.legalName());cancelEdit();refresh();},this::error);}
 private void error(Throwable e){String m=e==null?"Operation failed":e.getMessage();ModernDialog.error(table,"Recon Supplier","Operation failed",m==null?"Operation failed":m);}private static String s(String x){return x==null?"":x;}
}
